const raw = $input.first().json;
let payload;
let bodyText = raw.body;
if (typeof bodyText === 'string') { try { payload = JSON.parse(bodyText); } catch(e) { payload = { description: bodyText }; } }
else if (bodyText && typeof bodyText === 'object') { payload = bodyText; }
else { payload = raw; }
let questions = payload.questions;
if (typeof questions === 'string') questions = questions.split('\n');
if (!Array.isArray(questions)) questions = [];
questions = questions.map(q => String(q || '').trim()).filter(Boolean).slice(0, 15);
return [{ json: {
  mode: (payload.mode === 'score' ? 'score' : 'apply'),
  title: (payload.title || '').toString().substring(0, 300),
  company: (payload.company || '').toString().substring(0, 200),
  description: (payload.description || '').toString().substring(0, 8000),
  url: (payload.url || '').toString(),
  questions: questions
}}];

const job = $input.item.json;
const mode = job.mode || 'apply';
const PERFIL = "PERFIL DE SANTIAGO:
- Santiago Cione, 20 años, Buenos Aires Argentina. Español nativo, inglés fluido. Remoto only.
- AI Automation Specialist @ Desorbitante (agencia de Madrid, remoto, desde Mar 2026): pipeline de datos multi-fuente (Meta Ads/SalesRobot/Instantly -> n8n OAuth2/webhooks -> Supabase -> BigQuery -> Looker) para 6 clientes; CRM Instantly->GoHighLevel (onboarding 8h->2h); SalesRobot->Slack (-60% revisión manual).
- Co-Founder & CTO @ Gercio (SaaS de restaurantes, desde Nov 2025): Next.js 14 + Supabase + n8n self-hosted + agente GPT-4o-mini + Mercado Pago + Telegram. Pedidos 5min->30seg.
- Stack: n8n (avanzado, self-hosted VPS), APIs Claude/OpenAI (prompt engineering, agentes en prod), Supabase/PostgreSQL/BigQuery, Next.js/React/TS, Node, Python, OAuth2/webhooks/REST, Docker, Git.
- APIs con experiencia: Meta Ads, Mercado Pago, GoHighLevel, SalesRobot, Instantly, Telegram, Slack, Google Sheets.
- Educación: Ingeniería Informática ITBA (1er año). LinkedIn: linkedin.com/in/santiago-cione-7b3a50173. Email: your-email@example.com
- Experiencia en automatización/n8n: ~1.5 años en producción. Disponibilidad: inmediata, full remoto, cualquier timezone.
- Salario: NUNCA reveles tu salario actual ni tu situación financiera. Posicioná según el mercado de la empresa: US o startup bien financiada => USD 3500-5000/mes; europea => USD 2500-4000; LATAM => USD 1500-3000. Da SIEMPRE un rango (no número fijo) y enmarcalo en el valor que aportás, no en tu historia salarial. Si preguntan tu salario actual, desviá hacia tu expectativa.
- Usar "Specialist" no "Engineer" (sin título de grado; "Ingeniero" está protegido en España).
RED FLAGS a detectar: pide Senior/Lead/5+ años, on-site (no remoto), equity-only, rol puramente comercial/no técnico, requiere relocación.";
const TASK_SCORE = "TAREA (modo SCORE): Evaluá SOLO el fit del perfil con esta oferta. NO escribas cover letter ni respuestas.
fit_score 0-100 honesto: si pide 5+ años o es Lead/senior, bajá el score y marcá el red flag.
Devolvé SOLO JSON válido: {"job_title":"","company_name":"","language":"es|en","fit_score":0,"top_reasons":["r1","r2","r3"],"red_flags":["..."],"which_cv":"ES|EN","salary_note":"una línea de cómo posicionar el salario"}";
const TASK_APPLY = "TAREA (modo APPLY): Escribí una cover letter y, si hay preguntas de la aplicación, respondé cada una.
cover_letter: ~200-250 palabras, específica a ESTA oferta, con logros REALES de Santiago (números), en el idioma de la oferta, humana, sin inventar.
answers: para cada pregunta, respuesta en PRIMERA PERSONA como Santiago, en el idioma de la oferta, concreta y honesta. Preguntas sí/no o numéricas: directo y breve. Abiertas: 2-4 frases. Si no hay preguntas, [].
Devolvé SOLO JSON válido: {"job_title":"","company_name":"","language":"es|en","which_cv":"ES|EN","salary_note":"","cover_letter":"...","answers":[{"question":"","answer":""}]}";
const q = Array.isArray(job.questions) ? job.questions.filter(x => x && x.trim()) : [];
const task = mode === 'score' ? TASK_SCORE : TASK_APPLY;
const maxTokens = mode === 'score' ? 800 : 3000;
const system = PERFIL + '

' + task;
let user = 'OFERTA DE TRABAJO:
' + (job.title ? ('Título: ' + job.title + '
') : '') + (job.company ? ('Empresa: ' + job.company + '
') : '') + (job.url ? ('URL: ' + job.url + '
') : '') + '
Texto:
' + job.description;
if (mode === 'apply' && q.length) { user += '

PREGUNTAS DE LA APLICACIÓN (responder cada una en answers):
' + q.map((x, i) => (i + 1) + '. ' + x).join('
'); }
user += '

Responde ÚNICAMENTE con el objeto JSON pedido, sin texto adicional ni bloques de código markdown.';
const body = JSON.stringify({ model: 'claude-sonnet-4-6', max_tokens: maxTokens, system: system, messages: [ { role: 'user', content: user } ] });
return { json: Object.assign({}, job, { _llm_body: body, mode: mode }) };

const job = $('Build Prompt').item.json;
const mode = job.mode || 'apply';
const resp = $input.item.json;
let s;
try { let _raw=(resp.content&&resp.content[0]&&resp.content[0].text)||''; let _m=String(_raw).match(/\{[\s\S]*\}/); s=JSON.parse(_m?_m[0]:_raw); }
catch(e){ s={ job_title:'',company_name:'',language:'es',fit_score:0,top_reasons:['Error IA: '+e.message],red_flags:[],which_cv:'EN',salary_note:'',cover_letter:'',answers:[] }; }
const esc=(x)=>String(x||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const title=String(job.title||s.job_title||'Oferta').substring(0,480);
const company=String(job.company||s.company_name||'').substring(0,240);
const extId=String(job.url||('cl-'+Date.now())).split('?')[0].substring(0,255);

if (mode==='score') {
  return { json: {
    mode:'score', source:'linkedin_score', external_id:extId,
    title:title, company:company, url:job.url, description:String(job.description||'').substring(0,4000),
    score:Number(s.fit_score)||0, verdict:s.language||'',
    top_reasons:s.top_reasons||[], red_flags:s.red_flags||[],
    recommendation:s.which_cv||'', salary_range:String(s.salary_note||'').substring(0,255), status:'scored',
    fit_score:Number(s.fit_score)||0, which_cv:s.which_cv||'', language:s.language||'', salary_note:s.salary_note||''
  }};
}

const answers=Array.isArray(s.answers)?s.answers:[];
const baseMsg='📝 <b>'+esc(title)+'</b>\n🏢 '+esc(company)+'\nCV: '+esc(s.which_cv||'')+'  |  '+String(s.language||'').toUpperCase()+'\n\n✉️ <b>Cover letter:</b>\n'+esc(s.cover_letter||'');
const ansSection=answers.length?('\n\n❓ <b>Respuestas:</b>\n'+answers.map((a,i)=>'<b>'+(i+1)+'. '+esc(a.question)+'</b>\n'+esc(a.answer)).join('\n\n')):'';
let fullMsg=baseMsg+ansSection;
if (fullMsg.length>4000) fullMsg=baseMsg+'\n\n❓ '+answers.length+' respuesta(s) — vé la extensión.';
return { json: {
  mode:'apply', external_id:extId, title:title, company:company, url:job.url,
  which_cv:s.which_cv||'', language:s.language||'', salary_note:s.salary_note||'',
  cover_letter:s.cover_letter||'', answers:answers, telegram_message:fullMsg
}};

const m = $input.first().json;
const text = (m.message && m.message.text) || m.text || '';
return [{ json: { mode: 'apply', title: '', company: '', description: String(text).substring(0, 8000), url: '', questions: [] } }];
